\begin{aligned}
\mathrm{IsAdjunctionData}(F,G,\eta,\varepsilon)\leftrightarrow{}&\mathrm{IsNatural}(\eta,1_{\mathcal C},G\circ F)\land\mathrm{IsNatural}(\varepsilon,F\circ G,1_{\mathcal D})\\
&\land\forall A\in\mathrm{Ob}(\mathcal C)\ (\varepsilon_{F(A)}\circ_{\mathcal D}F(\eta_A)=\mathrm{id}_{\mathcal D}(F(A)))\\
&\land\forall B\in\mathrm{Ob}(\mathcal D)\ (G(\varepsilon_B)\circ_{\mathcal C}\eta_{G(B)}=\mathrm{id}_{\mathcal C}(G(B))).
\end{aligned}
